#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

void put_bit(int bit, int ctx) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * (-~*counts) / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;

  // Output bytes when fraction >= 256
  while (fraction >= 256) {
    putchar((fraction / 256) + 1);
    fraction = (fraction % 256);
  }
}

void put_integer(int val, int bits, int ctx) {
  int subtract_it = 1 << bits;
  val += subtract_it;

  ctx *= 99;
  int len = 0;
  int temp = val;
  while (temp > 1) {
    temp >>= 1;
    len++;
  }

  // Unary code for length
  while (len > bits) {
    put_bit(1, ++bits + ctx);
    len--;
  }
  put_bit(0, ++bits + ctx);

  // Binary code for value
  for (int i = bits - 1; i >= 0; i--) {
    put_bit((val >> i) & 1, ctx);
  }
}

int main() {
  char data[10000];
  int len = 0;

  // Read input data
  int c;
  while ((c = getchar()) != EOF && len < 10000) {
    data[len++] = c;
  }

  // Simple compression: mostly literals
  int ops = 0;
  int ops_pos = 0;

  // First, write the number of operations (we'll come back and patch this)
  ops_pos = fraction; // Remember where we started
  put_integer(len, INTOFF, 0);

  // Emit each character as a literal
  for (int i = 0; i < len; i++) {
    put_bit(0, 1); // Literal
    int sign = (data[i] < 0) ? 1 : 0;
    put_bit(sign, 8);
    unsigned char val = (unsigned char)data[i];
    if (sign) val = -val;
    for (int b = 3; b >= 0; b--) {
      put_bit((val >> b) & 1, 9);
    }
  }

  // Flush remaining bits
  if (fraction > 0) {
    putchar((fraction / 256) + 1);
  }

  return 0;
}
