#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

int bit_buffer = 0;
int bit_pos = 0;

void write_bit(int bit, int ctx) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
  }

  int *counts = cc + ctx * 2;
  int split = (int)(range * (-~*counts) / (*counts + counts[1] + 2));

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;

  while (fraction >= 256) {
    putchar((fraction / 256) + 1);
    fraction = fraction % 256;
  }
}

void write_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  val += subtract_it;

  ctx *= 99;

  // Write unary code: need to figure out how many bits in val
  int bits_needed = 0;
  int temp = val;
  while (temp > 1) {
    temp >>= 1;
    bits_needed++;
  }

  // Write leading 1s and final 0
  while (bits_needed > nbits) {
    write_bit(1, ++nbits + ctx);
    bits_needed--;
  }
  write_bit(0, ++nbits + ctx);

  // Write binary representation
  for (int i = nbits - 1; i >= 0; i--) {
    write_bit((val >> i) & 1, ctx);
  }
}

int main() {
  char data[10000];
  int len = 0;

  int c;
  while ((c = getchar()) != EOF && len < 10000) {
    data[len++] = (unsigned char)c;
  }

  // Write number of operations
  write_integer(len, INTOFF, 0);

  // Write each byte as a literal
  for (int i = 0; i < len; i++) {
    write_bit(0, 1);

    unsigned char ch = (unsigned char)data[i];
    int sign = (ch > 127) ? 1 : 0;
    int val = ch;

    if (sign) {
      val = 256 - val;
    }

    write_bit(sign, 8);
    write_integer(val, LITSIZE, 9);
  }

  // Flush any remaining fraction
  if (fraction > 0) {
    putchar((fraction / 256) + 1);
  }

  return 0;
}
