#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

void put_bit(int bit, int ctx) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
  }

  int *counts = cc + ctx * 2;
  int split = (int)(range * (-~*counts) / (*counts + counts[1] + 2));

  if (bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }

  counts[bit]++;

  while (fraction >= 256) {
    putchar((fraction / 256) + 1);
    fraction = fraction % 256;
  }
}

// Encode an integer using the same scheme as the decompressor expects
// value: the value to encode
// nbits: initial bit width (e.g., 4 for LITSIZE, 5 for OFF1)
// ctx: context for arithmetic coding
void put_integer(int value, int nbits, int ctx) {
  // We need to encode value such that when decoded:
  // result - (1 << nbits) = value
  // So result = value + (1 << nbits)

  int result = value + (1 << nbits);
  ctx *= 99;

  // Find how many bits we need to represent result
  int bits_needed = 0;
  int temp = result;
  while (temp > 1) {
    temp >>= 1;
    bits_needed++;
  }

  // Write unary code: (bits_needed - nbits) ones, then a zero
  int extra_bits = bits_needed - nbits;
  for (int i = 0; i < extra_bits; i++) {
    put_bit(1, ++nbits + ctx);
  }
  put_bit(0, ++nbits + ctx);

  // Write binary code: the remaining bits_needed bits of result
  // But result already has a leading 1, so we write the lower bits_needed bits
  for (int i = bits_needed - 1; i >= 0; i--) {
    put_bit((result >> i) & 1, ctx);
  }
}

int main() {
  char data[10000];
  int len = 0;

  int c;
  while ((c = getchar()) != EOF && len < 10000) {
    data[len++] = (unsigned char)c;
  }

  // Write number of operations
  put_integer(len, INTOFF, 0);

  // Write each byte as a literal
  for (int i = 0; i < len; i++) {
    // Bit 0: literal (not a reference)
    put_bit(0, 1);

    unsigned char ch = (unsigned char)data[i];

    // The decompressor does: char = (1-2*sign_bit) * value
    // If ch < 0 in signed terms (i.e., ch > 127), we need sign=1
    // If ch >= 0, we need sign=0

    // For unsigned char, we interpret:
    // If ch > 127, it's a negative number: sign=1, value=256-ch
    // If ch <= 127, it's positive: sign=0, value=ch

    int sign = (ch > 127) ? 1 : 0;
    int val = sign ? (256 - ch) : ch;

    put_bit(sign, 8);
    put_integer(val, LITSIZE, 9);
  }

  // Flush any remaining fraction
  if (fraction > 0) {
    putchar((fraction / 256) + 1);
  }

  return 0;
}
