// Manual bit-by-bit encoding to understand the format
int main() {
  // Let's manually create a compressed stream for a single character 'A' (65)

  // The decompressor expects:
  // 1. get_integer(9, 0) -> reads 9-bit integer = 1 (count of 1 operation)
  // 2. get_bit(1) -> 0 (literal, not reference)
  // 3. get_bit(8) -> 0 (sign bit, positive)
  // 4. get_integer(4, 9) -> 65 (the character value)

