  // result = 1 + 512 = 513 = 0b1000000001
  // bits_needed = 9
  // extra_bits = 0
  // So: write bit 0 (unary terminator), then 9 bits of 513 = 1000000001

  // For get_integer(4, 9) with value=65:
  // result = 65 + 16 = 81 = 0b1010001
  // bits_needed = 6
  // extra_bits = 2
  // So: write bits 1 1 0 (unary), then 6 bits of 81 = 010001

  printf("Manual encoding for 'A' (1 char):\n");
  printf("1. Unary+binary for count=1 (nbits=9):\n");
  printf("   result = 513 = 0b1000000001\n");
  printf("   unary: 0 (immediate)\n");
  printf("   binary: 000000001 (9 bits)\n");
  printf("\n2. Literal bit: 0\n");
  printf("\n3. Sign bit: 0\n");
  printf("\n4. Unary+binary for value=65 (nbits=4):\n");
  printf("   result = 81 = 0b1010001\n");
  printf("   unary: 1 1 0\n");
  printf("   binary: 010001 (6 bits)\n");
  printf("\nTotal bits: 0 + 9 + 1 + 1 + 1 + 1 + 0 + 6 = 19 bits\n");

  return 0;
}
